logic:
team  = player.info.team      // PlayerState+0x930
cache = data.cache            // OperationData+0x0

// ── 1) 정비(Repair) 필요 판정 : epic.rs:635
match v3_epicops_repair_need(team, cache, plan) {        // i8 반환
  1 => { self.objective = Some(MainObjective::Repair);    // +0x41f = 7   (637)
         self.chats.push(Chat::Repair(0));                // 태그 23      (638)
         return true; }
  2 => { self.objective = Some(MainObjective::Repair);    // +0x41f = 7   (642)
         return true; }                                   // 채팅 없음
  _ => {}                                                 // 0 및 그 외 → 아래로
}

// ── 2) 에픽 오브젝트(세르펜) 경합 : epic.rs:651~658
if is_object_being_taken_by_enemy(player, data, goal_data, self, /*flag=*/true)   // 651
   && v3_serpen_contest_clear_win(version, player, data, self) {                  // 652
     self.eo_serpen_punish_issues += 1;                                 // +0x410 (653)
     self.objective = Some(MainObjective::Serpen {                      // +0x41f = 1 (654)
         phase:       ObjectPhase::Setup,   // +0x420 = 1
         with_battle: true,                 // +0x421 = 1
     });
     self.chats.push(Chat::SerpenSetup(0));                             // 태그 25 (658)
     return true;
}
// ※ 651 이 false 면 652 를 건너뛰고, 651 true + 652 false 여도 같은 블록(%35)으로 합류한다.

// ── 3) 여기부터는 목표를 잡지 않는다. 압박 라인만 정하고 채팅.
let strategy = player.strategy(rnd, cache.game);            // 664, sret 24B
let mu = strategy.morgard_use;                              // 스택+4, 8B
let group_line: Option<LineType> = v3_epic_group_line(mu, player, data);   // 665
if group_line == None { return false; }                     // (-1 == None)

if self.v3_press_chat_line == group_line { return false; }  // 666 — 같은 라인이면 무동작

// ── 4) 누가 알릴지(announcer) 결정 : epic.rs:667~670, closure$0 (슬롯 5회 언롤)
let announcer: Option<usize> =
    (0..5).position(|x| {
        cache.player_champion[team][x].is_some()                         // 668, +0x1e0
        && v3_epic_formation_role(mu, Position::from_index(x), player, data)  // 669
              .is_some_and(|f| !f.is_split)                              // 670
    });
//  술어 상세: v3_epic_formation_role 은 {i8,i8} 을 돌려주고 .0 이
//  Option<V3EpicFormation> 의 니치 바이트다(V3EpicFormation{is_split:bool@0, line:LineType@1}).
//    0 = Some{is_split:false}, 1 = Some{is_split:true}, 2 = None
//  IR 은 xor(v != 2, v & 1) 로 계산 ⇒ true 는 오직 v == 0 (Some 이면서 is_split == false).
//  .1(= f.line) 은 사용하지 않는다.

// ── 5) 내가 announcer 면 채팅 : epic.rs:672~673
if announcer == Some(player.info.position.as_index()) {     // 672, +0x9c0
    self.chats.push(
        if self.v3_press_chat_line.is_none() { Chat::Press(group_line, 0) }       // 태그 21
        else                                 { Chat::PressChange(group_line, 0) } // 태그 22
    );                                                      // 673
}

self.v3_press_chat_line = group_line;                       // 679, +0x41e
return false;                                               // 682

// 반환 요약: true 는 Repair(2곳) / Serpen(1곳) 세 경로뿐. 나머지 전부 false.
